```cpp
int hoarePartition(vector<int> &a, int low, int high) {
    int pivot = a[(low + high) / 2];
    while (low <= high) {
        while (a[low] < pivot) low++;
        while (a[high] > pivot) high--;
        if (low <= high) {
            swap(a[low], a[high]);
            ______;
        }
    }
    return high;
}
```

